import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_prime_powers(limit):
    count = 0

    # Set to store found prime powers to avoid double counting (e.g., 64 = 2^6 = 4^3, though we only check for prime bases)
    prime_powers = set()

    # 1. Iterate through all possible prime bases p
    # Since 2^k <= 2000, the largest possible prime base p is 1999 (k=1).
    # We only need to check primes up to the limit itself.

    primes = []
    sieve_limit = limit
    is_prime_sieve = [True] * (sieve_limit + 1)
    is_prime_sieve[0] = is_prime_sieve[1] = False
    for p in range(2, sieve_limit + 1):
        if is_prime_sieve[p]:
            primes.append(p)
            for i in range(p * p, sieve_limit + 1, p):
                is_prime_sieve[i] = False

    for p in primes:
        # 2. Iterate through powers k >= 1
        power = p
        while power <= limit:
            if power >= 2:
                prime_powers.add(power)

            # Check for overflow before multiplying, though 2000 is small enough
            if limit // p < power:
                break

            power *= p

    return len(prime_powers)

LIMIT = 2000
result = count_prime_powers(LIMIT)
print(result)
